node << 'EOF'
const fs = require("fs");
const zlib = require("zlib");

// Minimal zip reader for .docx (which is a zip archive)
const buf = fs.readFileSync("/workspace/testbed/docs/customer_report.docx");

// Parse zip central directory
// End of central directory record signature = 0x06054b50
let eocdOffset = -1;
for (let i = buf.length - 22; i >= 0; i--) {
  if (buf.readUInt32LE(i) === 0x06054b50) { eocdOffset = i; break; }
}
if (eocdOffset === -1) { console.error("Not a valid zip"); process.exit(1); }

const cdOffset = buf.readUInt32LE(eocdOffset + 16);
const cdEntries = buf.readUInt16LE(eocdOffset + 10);

let entries = [];
let off = cdOffset;
for (let i = 0; i < cdEntries; i++) {
  const sig = buf.readUInt32LE(off);
  if (sig !== 0x02014b50) break;
  const method = buf.readUInt16LE(off + 10);
  const compSize = buf.readUInt32LE(off + 20);
  const uncompSize = buf.readUInt32LE(off + 24);
  const nameLen = buf.readUInt16LE(off + 28);
  const extraLen = buf.readUInt16LE(off + 30);
  const commentLen = buf.readUInt16LE(off + 32);
  const localHeaderOff = buf.readUInt32LE(off + 42);
  const name = buf.toString("utf8", off + 46, off + 46 + nameLen);
  entries.push({ name, method, compSize, uncompSize, localHeaderOff });
  off += 46 + nameLen + extraLen + commentLen;
}

function readEntry(entry) {
  const lOff = entry.localHeaderOff;
  const lNameLen = buf.readUInt16LE(lOff + 26);
  const lExtraLen = buf.readUInt16LE(lOff + 28);
  const dataStart = lOff + 30 + lNameLen + lExtraLen;
  const raw = buf.slice(dataStart, dataStart + entry.compSize);
  if (entry.method === 0) return raw;
  if (entry.method === 8) return zlib.inflateRawSync(raw);
  throw new Error("Unsupported method " + entry.method);
}

const docEntry = entries.find(e => e.name === "word/document.xml");
if (!docEntry) { console.error("No word/document.xml found"); process.exit(1); }

const xml = readEntry(docEntry).toString("utf8");

// Parse paragraphs: extract text from <w:t> nodes within each <w:p>
const paragraphs = [];
const pRegex = /<w:p[\s>][\s\S]*?<\/w:p>/g;
let pMatch;
while ((pMatch = pRegex.exec(xml)) !== null) {
  const pXml = pMatch[0];
  const tRegex = /<w:t[^>]*>([\s\S]*?)<\/w:t>/g;
  let tMatch;
  let text = "";
  while ((tMatch = tRegex.exec(pXml)) !== null) {
    text += tMatch[1];
  }
  paragraphs.push(text);
}

console.log(paragraphs.join("\n"));
EOF

