const fs = require("fs");
const zlib = require("zlib");
const PDFDocument = require("pdfkit");

// --- Extract text from .docx ---
const docxPath = "/workspace/testbed/docs/customer_report.docx";
const buf = fs.readFileSync(docxPath);

let eocdOffset = -1;
for (let i = buf.length - 22; i >= 0; i--) {
  if (buf.readUInt32LE(i) === 0x06054b50) { eocdOffset = i; break; }
}
const cdOffset = buf.readUInt32LE(eocdOffset + 16);
const cdEntries = buf.readUInt16LE(eocdOffset + 10);

let entries = [];
let off = cdOffset;
for (let i = 0; i < cdEntries; i++) {
  const method = buf.readUInt16LE(off + 10);
  const compSize = buf.readUInt32LE(off + 20);
  const nameLen = buf.readUInt16LE(off + 28);
  const extraLen = buf.readUInt16LE(off + 30);
  const commentLen = buf.readUInt16LE(off + 32);
  const localHeaderOff = buf.readUInt32LE(off + 42);
  const name = buf.toString("utf8", off + 46, off + 46 + nameLen);
  entries.push({ name, method, compSize, localHeaderOff });
  off += 46 + nameLen + extraLen + commentLen;
}

function readEntry(entry) {
  const lOff = entry.localHeaderOff;
  const lNameLen = buf.readUInt16LE(lOff + 26);
  const lExtraLen = buf.readUInt16LE(lOff + 28);
  const dataStart = lOff + 30 + lNameLen + lExtraLen;
  const raw = buf.slice(dataStart, dataStart + entry.compSize);
  if (entry.method === 0) return raw;
  if (entry.method === 8) return zlib.inflateRawSync(raw);
  throw new Error("Unsupported method " + entry.method);
}

const docEntry = entries.find(e => e.name === "word/document.xml");
const xml = readEntry(docEntry).toString("utf8");

// Parse paragraphs with bold detection
const WORD_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
const pRegex = /<w:p[\s>][\s\S]*?<\/w:p>/g;
const rRegex = /<w:r>([\s\S]*?)<\/w:r>|<w:r\s[^>]*>([\s\S]*?)<\/w:r>/g;
const tRegex = /<w:t[^>]*>([\s\S]*?)<\/w:t>/g;

let paragraphs = [];
let pMatch;
while ((pMatch = pRegex.exec(xml)) !== null) {
  const pXml = pMatch[0];
  // Check if paragraph has a style (heading, title)
  const pStyleMatch = pXml.match(/<w:pStyle\s+w:val="([^"]+)"/);
  const style = pStyleMatch ? pStyleMatch[1] : null;

  // Collect runs with bold info
  let runs = [];
  let rMatch;
  const rRegex2 = /<w:r[\s>][\s\S]*?<\/w:r>/g;
  while ((rMatch = rRegex2.exec(pXml)) !== null) {
    const rXml = rMatch[0];
    const isBold = /<w:b[\s/>]/.test(rXml) || /<w:b\s+w:val="true"/.test(rXml);
    let text = "";
    let tM;
    const tReg = /<w:t[^>]*>([\s\S]*?)<\/w:t>/g;
    while ((tM = tReg.exec(rXml)) !== null) text += tM[1];
    if (text) runs.push({ text, bold: isBold });
  }

  let fullText = runs.map(r => r.text).join("");
  paragraphs.push({ text: fullText, runs, style });
}

// --- Build PDF ---
const pdfPath = "/workspace/testbed/docs/customer_report.pdf";
const doc = new PDFDocument({ margin: 50 });
const stream = fs.createWriteStream(pdfPath);
doc.pipe(stream);

for (const para of paragraphs) {
  if (!para.text && para.runs.length === 0) {
    doc.moveDown(0.5);
    continue;
  }

  // Title
  if (para.style === "Title" || para.style === "Heading1" ||
      (para === paragraphs[0] && para.text === "Customer Activity Report")) {
    doc.fontSize(20).font("Helvetica-Bold").text(para.text, { align: "center" });
    doc.moveDown(0.8);
    continue;
  }

  // Customer name lines (bold, no colon — heuristic)
  const isCustomerName = para.runs.length > 0 && para.runs.every(r => r.bold) && !para.text.includes(":");
  if (isCustomerName && para.text.trim().length > 0) {
    doc.moveDown(0.5);
    doc.fontSize(14).font("Helvetica-Bold").text(para.text);
    doc.moveDown(0.2);
    continue;
  }

  // Regular / mixed paragraph
  if (para.text.startsWith("  Items:")) {
    doc.fontSize(9).font("Helvetica").text(para.text, { indent: 20 });
  } else if (para.text.startsWith("Order ORD-")) {
    doc.fontSize(10).font("Helvetica").text(para.text, { indent: 10 });
  } else {
    doc.fontSize(10).font("Helvetica").text(para.text);
  }
}

doc.end();
stream.on("finish", () => {
  const stats = fs.statSync(pdfPath);
  console.log("PDF created: " + pdfPath + " (" + (stats.size / 1024).toFixed(1) + " KB)");
});
