# Let's just manually parse the PDF text streams since it's a simple pdfkit-generated file
node << 'EOF'
const fs = require("fs");
const zlib = require("zlib");

const pdf = fs.readFileSync("/workspace/testbed/docs/customer_report.pdf");
const pdfStr = pdf.toString("binary");

// Find all stream objects and decompress them
const streams = [];
let idx = 0;
while (true) {
  const streamStart = pdfStr.indexOf("stream\r\n", idx);
  const streamStart2 = pdfStr.indexOf("stream\n", idx);
  let sStart = -1;
  let offset = 0;
  if (streamStart === -1 && streamStart2 === -1) break;
  if (streamStart === -1) { sStart = streamStart2; offset = 7; }
  else if (streamStart2 === -1) { sStart = streamStart; offset = 8; }
  else { sStart = Math.min(streamStart, streamStart2); offset = sStart === streamStart ? 8 : 7; }

  const dataStart = sStart + offset;
  const endStream = pdfStr.indexOf("endstream", dataStart);
  if (endStream === -1) break;

  const rawData = Buffer.from(pdfStr.substring(dataStart, endStream), "binary");
  try {
    const inflated = zlib.inflateSync(rawData);
    streams.push(inflated.toString("utf8"));
  } catch(e) {
    // try as-is
    streams.push(rawData.toString("utf8"));
  }
  idx = endStream + 9;
}

// Extract text from PDF content streams (Tj and TJ operators)
for (const s of streams) {
  // Match text showing operators
  const lines = s.split("\n");
  let textParts = [];
  for (const line of lines) {
    // (text) Tj
    const tjMatch = line.match(/\((.+?)\)\s*Tj/);
    if (tjMatch) {
      textParts.push(tjMatch[1]);
    }
    // TJ array: [(text) num (text) ...]
    const tjArrayMatch = line.match(/\[(.*?)\]\s*TJ/);
    if (tjArrayMatch) {
      const inner = tjArrayMatch[1];
      const parts = inner.match(/\(([^)]*)\)/g);
      if (parts) {
        const combined = parts.map(p => p.slice(1, -1)).join("");
        textParts.push(combined);
      }
    }
  }
  if (textParts.length > 0) {
    console.log(textParts.join("\n"));
  }
}
EOF

# Let's look at the raw PDF content streams more carefully
node << 'EOF'
const fs = require("fs");
const zlib = require("zlib");

const pdf = fs.readFileSync("/workspace/testbed/docs/customer_report.pdf");

// Find streams by searching for "stream" keyword
const results = [];
let pos = 0;
while (pos < pdf.length) {
  // Find "stream\n" or "stream\r\n"
  const idx1 = pdf.indexOf(Buffer.from("stream\n"), pos);
  const idx2 = pdf.indexOf(Buffer.from("stream\r\n"), pos);
  let sIdx, skip;
  if (idx1 === -1 && idx2 === -1) break;
  if (idx1 === -1) { sIdx = idx2; skip = 8; }
  else if (idx2 === -1) { sIdx = idx1; skip = 7; }
  else if (idx1 < idx2) { sIdx = idx1; skip = 7; }
  else { sIdx = idx2; skip = 8; }

  const dataStart = sIdx + skip;
  const endIdx = pdf.indexOf(Buffer.from("endstream"), dataStart);
  if (endIdx === -1) break;

  const raw = pdf.slice(dataStart, endIdx);
  try {
    const inflated = zlib.inflateSync(raw);
    results.push(inflated.toString("utf8"));
  } catch (e) {
    try {
      const inflated = zlib.inflateRawSync(raw);
      results.push(inflated.toString("utf8"));
    } catch(e2) {
      results.push("[binary/undecompressable stream]");
    }
  }
  pos = endIdx + 9;
}

// Parse PDF text operators from content streams
for (let i = 0; i < results.length; i++) {
  const content = results[i];
  if (content.includes("[binary")) continue;

  // Extract text between parentheses in Tj/TJ operators
  const textPieces = [];
  // Handle TJ arrays and Tj
  const regex = /\(([^\\)]*(?:\\.[^\\)]*)*)\)/g;
  let m;
  while ((m = regex.exec(content)) !== null) {
    // Unescape PDF string
    let t = m[1]
      .replace(/\\n/g, "\n")
      .replace(/\\r/g, "\r")
      .replace(/\\t/g, "\t")
      .replace(/\\\(/g, "(")
      .replace(/\\\)/g, ")")
      .replace(/\\\\/g, "\\");
    if (t.trim()) textPieces.push(t);
  }
  if (textPieces.length > 0) {
    console.log("--- Page " + (i+1) + " ---");
    console.log(textPieces.join("\n"));
  }
}
