const fs = require("fs");
const zlib = require("zlib");

const pdf = fs.readFileSync("/workspace/testbed/docs/customer_report.pdf");
const pdfText = pdf.toString("latin1");

// Find all stream boundaries
let pos = 0;
let streamNum = 0;
while (pos < pdfText.length) {
  const idx = pdfText.indexOf("stream", pos);
  if (idx === -1) break;

  // Check it's actually "stream\n" or "stream\r\n"
  const nextChar = pdfText[idx + 6];
  if (nextChar !== "\n" && nextChar !== "\r") { pos = idx + 6; continue; }

  const skip = (nextChar === "\r" && pdfText[idx + 7] === "\n") ? 8 : 7;
  const dataStart = idx + skip;

  const endIdx = pdfText.indexOf("endstream", dataStart);
  if (endIdx === -1) break;

  const raw = pdf.slice(dataStart, endIdx);
  streamNum++;

  let decoded = null;
  try { decoded = zlib.inflateSync(raw).toString("utf8"); } catch(e) {}
  if (!decoded) try { decoded = zlib.inflateRawSync(raw).toString("utf8"); } catch(e) {}
  if (!decoded) decoded = raw.toString("utf8");

  console.log(`\n=== Stream #${streamNum} (${raw.length} bytes) ===`);
  console.log(decoded.substring(0, 2000));

  pos = endIdx + 9;
}
