# Now decode the hex strings to readable text
node << 'EOF'
const fs = require("fs");
const zlib = require("zlib");

const pdf = fs.readFileSync("/workspace/testbed/docs/customer_report.pdf");
const pdfText = pdf.toString("latin1");

let pos = 0;
let allText = [];
let streamNum = 0;

while (pos < pdfText.length) {
  const idx = pdfText.indexOf("stream", pos);
  if (idx === -1) break;
  const nextChar = pdfText[idx + 6];
  if (nextChar !== "\n" && nextChar !== "\r") { pos = idx + 6; continue; }
  const skip = (nextChar === "\r" && pdfText[idx + 7] === "\n") ? 8 : 7;
  const dataStart = idx + skip;
  const endIdx = pdfText.indexOf("endstream", dataStart);
  if (endIdx === -1) break;
  const raw = pdf.slice(dataStart, endIdx);
  streamNum++;
  let decoded;
  try { decoded = zlib.inflateSync(raw).toString("utf8"); } catch(e) {
    try { decoded = zlib.inflateRawSync(raw).toString("utf8"); } catch(e2) {
      decoded = raw.toString("utf8");
    }
  }

  // Extract hex strings from TJ operators: <hex>
  const hexRegex = /<([0-9a-fA-F]+)>/g;
  let m;
  let lineTexts = [];
  const lines = decoded.split("\n");

  for (const line of lines) {
    if (!line.includes("TJ") && !line.includes("Tj")) continue;
    let parts = [];
    while ((m = hexRegex.exec(line)) !== null) {
      const hex = m[1];
      let str = "";
      for (let i = 0; i < hex.length; i += 2) {
        str += String.fromCharCode(parseInt(hex.substring(i, i+2), 16));
      }
      parts.push(str);
    }
    if (parts.length > 0) lineTexts.push(parts.join(""));
  }

  if (lineTexts.length > 0) {
    allText.push(`--- Page ${streamNum} ---`);
    allText.push(lineTexts.join("\n"));
  }

  pos = endIdx + 9;
}

console.log(allText.join("\n"));
