const nodemailer = require("nodemailer");
const path = require("path");

const SMTP_PASS = process.env.SMTP_PASS;
if (!SMTP_PASS) {
  console.error("Error: SMTP_PASS environment variable is not set.");
  process.exit(1);
}

const transporter = nodemailer.createTransport({
  host: "smtp.example.com",
  port: 587,
  secure: false, // STARTTLS on port 587
  auth: {
    user: "alice@example.com",
    pass: SMTP_PASS,
  },
});

const mailOptions = {
  from: "alice@example.com",
  to: "bob@example.com",
  subject: "Customer Activity Report",
  text: "Hi Bob,\n\nPlease find the Customer Activity Report attached for your review.\n\nBest regards,\nAlice",
  attachments: [
    {
      filename: "customer_report.pdf",
      path: path.join(__dirname, "testbed/docs/customer_report.pdf"),
    },
  ],
};

transporter.sendMail(mailOptions, (err, info) => {
  if (err) {
    console.error("Failed to send email:", err.message);
    process.exit(1);
  }
  console.log("Email sent successfully!");
  console.log("Message ID:", info.messageId);
  console.log("Response:", info.response);
});
